  ensures if (i < len(xs)) then (result == Some(xs[i])) else (result == None)
  effects pure
  example (nth([5, 6, 7], 1) == Some(6))
  example (nth([5, 6, 7], 3) == None)
  example (nth([], 0) == None)
{
  match xs { [] => None [h, ..t] => if (i == 0) then Some(h) else nth(h, (i - 1)) }
}

